<script>$(function(){$('.bd-select').select2({width:'100%',minimumResultsForSearch:Infinity})});const box=document.querySelector('[data-expiry]');if(box&&box.dataset.active==='1'){const out=box.querySelector('.bd-countdown'),end=new Date(box.dataset.expiry);function tick(){let ms=end-new Date;if(ms<=0){out.textContent='EXPIRED';out.style.color='#dc2626';return}const d=Math.floor(ms/86400000);ms%=86400000;const h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000);out.textContent='Time left: '+(d?d+'d ':'')+h+'h '+m+'m';if(!d&&h<3)out.style.color='#dc2626'}tick();setInterval(tick,60000)}</script>
